SELECT 
FROM app_user
WHERE username = #{identity}
   OR email = #{identity}
ORDER BY CASE WHEN username = #{identity} THEN 0 ELSE 1 END
LIMIT 1

SELECT 
FROM app_user
WHERE username = #{identity}
   OR display_name = #{identity}
ORDER BY CASE WHEN username = #{identity} THEN 0 ELSE 1 END
LIMIT 1

SELECT COUNT(*)
FROM app_user
WHERE username = #{username}

SELECT COUNT(*)
FROM app_user
WHERE email = #{email}

SELECT COUNT(*)
FROM app_user
WHERE avatar_url = #{avatarUrl}

mapper.update:
UPDATE app_user
SET avatar_url = #{avatarUrl}
WHERE username = #{username}
  AND active = TRUE

UPDATE app_user
SET active = #{active}
WHERE id = #{id}

UPDATE app_user
SET role = #{role}
WHERE id = #{id}

UPDATE app_user
SET password = #{password}
WHERE username = #{username}
  AND LOWER(email) = #{email}
  AND active = TRUE

